import{_ as e,o as l,c as t,a5 as i}from"./chunks/framework.BPFk9-tb.js";const _=JSON.parse('{"title":"写作课作业-083","description":"","frontmatter":{"date":"2020-10-22T19:35:36","title":"写作课作业-083","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/083.md","filePath":"posts/homework/083.md"}'),a={name:"posts/homework/083.md"};function r(c,o,p,u,s,n){return l(),t("div",null,[...o[0]||(o[0]=[i('<blockquote><p>10.10写作作业：《微信互联网平民创业》之《15. 怎样才能成为不讨厌的人?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>那「不讨人厌」的诀窍在哪里呢?只要再剔除一个恶习就好了，真的很简单，很直接:</p><blockquote><p>以自我为中心</p></blockquote></blockquote><blockquote><p>任何正常人在成⻓过程中都有可能需要经过这四个阶段，只不过，并不是所有人都能到 达第四个阶段，有很多人停留在第三个阶段，有人停留在第二个阶段，甚至还有人干脆 一直停留在第一个阶段:</p><blockquote><ol><li>你行，我不行(You’re OK, I’m not OK)</li><li>我不行，你也不行(I’m not OK, you’re not OK too)</li><li>我行，你不行(I’m OK, you’re not OK)</li><li>我行，你也行(I’m OK, and you’re also OK)</li></ol></blockquote></blockquote><blockquote><p>调整一下自己的状态，经常按以下思路整理自己的情绪就好了:</p><blockquote><ul><li>我行就行，不行就不行;</li><li>不行并不丢人，不行就学，学到做到为止;</li><li>至于别人行还是不行，关我什么事儿?</li></ul></blockquote><p>就这么简单。如此这般，要么你在第四个阶段，要么你在第一个阶段 —— 反正你就是不 在「无论如何都会让你讨人厌的第二个或者第三个阶段」。说实话，这多少有点诡异! 因为到最后，治疗「以自我为中心」的手段竟然是「在自己身上使劲」—— 即，只关注自己的成⻓，不与他人做无谓的比较。</p></blockquote><blockquote><p>如此这般，你就能在「不小心显然第二或第三个阶段的情况下」，能够及时意识到，然 后还能及时跳出来。在第二或第三个阶段里的每一分每一秒都是浪费。因为无论是你的 时间，还是你的精力，甚至是情绪，都对你毫无用处。毫无用处到也罢了，它还会不断 令你变成更讨人厌的人...... 这太可怕了。不招人喜欢到也罢了，讨人厌不仅非常不好， 还非常没必要。</p><p>关键在于，讨人厌的人那可是真的赚不到钱啊!</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>当看到“以自我为中心”的时候，其实是挺纳闷的，对于举的例子：</p><ul><li>经常打断他人说话;</li><li>不放过任何抬高自己的机会;</li><li>为了证明自己是对的不惜一切代价;</li><li>如若话题不在自己身上那么几乎全都是抱怨或者负面评价;</li></ul><p>在我看来也都是“以自我为中心”的表现，当我继续往下看，看到了《I’m OK, You’re OK》那一段，哦，这是《通往财富自由之路》里面讲过的内容呀，而这里的“以自我为中心”，其实是将自己的注意力放在自己身上，自己的成长身上。而与通常所说的”以自我为中心“的，为了引起他人对自己的注意，表现自己，而没有顾及他人的感受。</p><p>现在开始做晨间笔记，这个天天反省的模板就很好。</p>',11)])])}const d=e(a,[["render",r]]);export{_ as __pageData,d as default};
